entries[84101] = { ["name"] = "Reins of the Grand Expedition Yak", ["text"] = "Binds when picked up\nMount\nRequires Level 85\nRequires Journeyman Riding\nUse: Teaches you how to summon this three-person mount with vendors. Excellent for those long journies up the summit of Mount Neverest. Be the envy of your friends.\nCalls forth the Grand Expedition Yak, complete with helpful grummles for all your vendor needs.\nSell Price:" }
