entries[84122] = { ["name"] = "Recipe: Alchemist's Flask", ["text"] = "Requires Alchemy (550)\nUse: Teaches you how to mix an Alchemist's Flask.\n\nAlchemist's Flask\nBinds when picked up\nRequires Alchemy (300)\nUse: Increases your Agility, Strength, or Intellect by 320 for 2 hrs. Your highest stat is always chosen.\n\nCounts as both a Battle and Guardian elixir. Effect persists through death.\n\"Can be used in arenas. This potent flask is not consumed when used, but is unaffected by Mixology.\"\nRequires Crystal Vial , Icecap (7), Mountain Silversage (7), Ghost Mushroom (7)" }
entries[84123] = { ["name"] = "Recipe: Flask of Falling Leaves", ["text"] = "Requires Alchemy (550)\nUse: Teaches you how to mix a Flask of Falling Leaves.\nWhen making this flask, you have a chance to learn additional recipes.\n\nThe number of recipes you can learn is limited by your skill in Alchemy.\n\nFlask of Falling Leaves\nRequires Level 85\nUse: Increases Spirit by 1000 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Crystal Vial , Green Tea Leaf (4), Golden Lotus" }
