entries[84987] = { ["name"] = "Malevolent Gladiator's Plate Chestpiece", ["text"] = "Season 12 Elite\nBinds when picked up\nChest Plate\n5284 Armor\n+924 Strength\n+1,626 Stamina\n+ 563 Critical Strike\n+ 723 Haste\n+ 433 PvP Power\n\nRed Socket\nYellow Socket\nSocket Bonus: + 120 PvP Power\n\nDurability 165 / 165\nClasses: Warrior\nRequires Level 90\n\nGladiator's Battlegear (0/5)\nGladiator's Plate Chestpiece\nGladiator's Plate Gauntlets\nGladiator's Plate Helm\nGladiator's Plate Legguards\nGladiator's Plate Shoulders\n(2) Set : Disarm duration reduced by 50%.\n(2) Set : Increases PvP power by 500.\n(4) Set : Increases your speed by 70% for 3 sec after using Heroic Leap.\n(4) Set : Increases PvP Power by 1000.\nSell Price:" }
entries[84988] = { ["name"] = "Malevolent Gladiator's Mail Armor", ["text"] = "Season 12 Elite\nBinds when picked up\nChest Mail\n3869 Armor\n+1,626 Stamina\n+924 Intellect\n+ 563 Critical Strike\n+ 723 Haste\n+ 433 PvP Power\n\nRed Socket\nYellow Socket\nSocket Bonus: + 120 PvP Power\n\nDurability 165 / 165\nClasses: Shaman\nRequires Level 90\n\nGladiator's Thunderfist (0/5)\nGladiator's Mail Armor\nGladiator's Mail Gauntlets\nGladiator's Mail Helm\nGladiator's Mail Leggings\nGladiator's Mail Spaulders\n(2) Set : Increases PvP power by 500.\n(2) Set : Your Lightning Shield can now be triggered once every 1.5 sec instead of once every 3 sec.\n(4) Set : Increases PvP Power by 1000.\n(4) Set : Reduces the cooldown of your Thunderstorm spell by 50%.\nSell Price:" }
